(function(){
  const DOG_FRAMES = {"idle": ["data:image/png;base64,", "data:image/png;base64,", "data:image/png;base64,", "data:image/png;base64,", "data:image/png;base64,"], "walk": ["data:image/png;base64,", "data:image/png;base64,", "data:image/png;base64,", "data:image/png;base64,", "data:image/png;base64,", "data:image/png;base64,", "data:image/png;base64,", "data:image/png;base64,"], "run": ["data:image/png;base64,", "data:image/png;base64,", "data:image/png;base64,", "data:image/png;base64,", "data:image/png;base64,", "data:image/png;base64,", "data:image/png;base64,", "data:image/png;base64,"], "eat": ["data:image/png;base64,", "data:image/png;base64,", "data:image/png;base64,", "data:image/png;base64,", "data:image/png;base64,", "data:image/png;base64,"], "sleep": ["data:image/png;base64,", "data:image/png;base64,", "data:image/png;base64,", "data:image/png;base64,", "data:image/png;base64,"], "play": ["data:image/png;base64,", "data:image/png;base64,", "data:image/png;base64,", "data:image/png;base64,", "data:image/png;base64,", "data:image/png;base64,"]};
  const ACTION_LABELS = { idle:'待機', walk:'走路', run:'跑來迎接', eat:'吃飯', sleep:'睡覺', play:'追球' };
  let currentMode = 'my';
  let busy = false;
  let timer = null;
  let firstPetOpen = true;

  function ensureState(){
    if(typeof window.st !== 'object' || !window.st) window.st = {};
    if(!st.petDogHome || typeof st.petDogHome !== 'object'){
      st.petDogHome = { hunger:82, happy:85, clean:84, energy:86, totalCare:0 };
    }
    return st.petDogHome;
  }

  function saveAll(){
    try{ if(typeof save === 'function') save(); }catch(e){}
    try{ if(typeof header === 'function') header(); }catch(e){}
  }

  function clamp(v){ return Math.max(0, Math.min(100, Number(v)||0)); }
  function qs(id){ return document.getElementById(id); }
  function stopAnim(){ if(timer){ clearInterval(timer); timer = null; } }
  function say(text){
    const el = qs('dogHomeSpeech');
    if(!el) return;
    el.textContent = text;
    el.classList.remove('show');
    void el.offsetWidth;
    el.classList.add('show');
  }
  function setActionLabel(action, idx){
    const box = qs('dogHomeFrameInfo');
    if(!box) return;
    const total = (DOG_FRAMES[action]||[]).length;
    box.innerHTML = '<b>' + (ACTION_LABELS[action]||action) + '</b><span>' + (idx+1) + ' / ' + total + '</span>';
  }
  function setFrame(action, idx){
    const img = qs('dogHomeDog');
    if(!img) return;
    const frames = DOG_FRAMES[action] || DOG_FRAMES.idle;
    const i = Math.max(0, Math.min(frames.length-1, idx));
    img.src = frames[i];
    setActionLabel(action, i);
  }
  function loop(action, fps){
    stopAnim();
    const frames = DOG_FRAMES[action] || DOG_FRAMES.idle;
    let i = 0;
    setFrame(action, 0);
    timer = setInterval(() => {
      i = (i + 1) % frames.length;
      setFrame(action, i);
    }, Math.round(1000 / fps));
  }
  function playOnce(action, fps, loops=1){
    return new Promise(resolve => {
      stopAnim();
      const frames = DOG_FRAMES[action] || DOG_FRAMES.idle;
      let i = 0, count = 0;
      setFrame(action, 0);
      timer = setInterval(() => {
        i += 1;
        if(i >= frames.length){
          i = 0;
          count += 1;
          if(count >= loops){
            stopAnim();
            setFrame(action, frames.length - 1);
            resolve();
            return;
          }
        }
        setFrame(action, i);
      }, Math.round(1000 / fps));
    });
  }
  function disableButtons(v){
    document.querySelectorAll('.dog-home-actions button').forEach(btn => btn.disabled = !!v);
  }
  function wait(ms){ return new Promise(r => setTimeout(r, ms)); }
  function addCoins(n){
    if(typeof st.coins !== 'number') st.coins = Number(st.coins) || 0;
    st.coins += n;
  }

  function renderDogHome(){
    const host = qs('petHomePanel');
    if(!host) return;
    const s = ensureState();
    const coins = Number(st.coins)||0;
    host.innerHTML = `
      <div class="dog-home-shell">
        <div class="dog-home-topbar">
          <div class="dog-home-title">🐶 毛孩之家</div>
          <div class="dog-home-subtitle">小狗搶先版｜逐格動畫互動模式</div>
          <div class="dog-home-coin">守護金幣 ${coins}</div>
        </div>
        <div class="dog-home-switchers">
          <button class="active" type="button">🐶 小狗</button>
          <button class="coming" type="button" disabled>🐱 貓咪（之後加入）</button>
          <button class="coming" type="button" disabled>🐰 兔兔（之後加入）</button>
        </div>
        <div class="dog-home-room">
          <div class="dog-home-window">☁️ 🌿</div>
          <div class="dog-home-bed">🛏️</div>
          <div class="dog-home-bowl">🥣</div>
          <div class="dog-home-ball" id="dogHomeBall">🔴</div>
          <div class="dog-home-door">🚪</div>
          <div class="dog-home-speech" id="dogHomeSpeech">歡迎回來！</div>
          <div class="dog-home-stats">
            <div><span>💗 心情</span><i><b style="width:${s.happy}%"></b></i><strong>${s.happy}</strong></div>
            <div><span>🥣 飽足</span><i><b style="width:${s.hunger}%"></b></i><strong>${s.hunger}</strong></div>
            <div><span>🫧 清潔</span><i><b style="width:${s.clean}%"></b></i><strong>${s.clean}</strong></div>
            <div><span>⚡ 活力</span><i><b style="width:${s.energy}%"></b></i><strong>${s.energy}</strong></div>
          </div>
          <div class="dog-home-frame-info" id="dogHomeFrameInfo"><b>待機</b><span>1 / 5</span></div>
          <div class="dog-home-note">這版使用真正的逐格小狗動畫，不再用骨架旋轉。</div>
          <div class="dog-home-dog" id="dogHomePet"><img id="dogHomeDog" alt="互動小狗"/></div>
        </div>
        <div class="dog-home-actions">
          <button onclick="dogHomeAction('pet')" type="button">💗<b>迎接主人</b></button>
          <button onclick="dogHomeAction('walk')" type="button">🐾<b>走一走</b></button>
          <button onclick="dogHomeAction('feed')" type="button">🥣<b>餵食</b></button>
          <button onclick="dogHomeAction('sleep')" type="button">🌙<b>睡覺</b></button>
          <button onclick="dogHomeAction('play')" type="button">🎾<b>追球</b></button>
          <button onclick="dogHomeAction('idle')" type="button">😊<b>待機</b></button>
        </div>
      </div>`;
    setFrame('idle',0);
    loop('idle',4);
  }

  function ensureBaseLayout(){
    const basePage = qs('basePage');
    if(!basePage) return null;

    let tabs = qs('baseQuickTabs');
    let petSection = qs('petHomeSection');
    let myView = qs('myBaseView');

    if(!tabs){
      tabs = document.createElement('div');
      tabs.id = 'baseQuickTabs';
      tabs.className = 'base-quick-tabs';
      tabs.innerHTML = '<button type="button" data-mode="my" class="active">🌍 我的基地</button><button type="button" data-mode="pet">🐾 毛孩之家</button>';
      basePage.insertBefore(tabs, basePage.firstChild);
    }

    if(!petSection){
      petSection = document.createElement('section');
      petSection.id = 'petHomeSection';
      petSection.className = 'dog-home-section hide';
      petSection.innerHTML = '<div id="petHomePanel"></div>';
      basePage.appendChild(petSection);
    } else if(!qs('petHomePanel')) {
      petSection.innerHTML = '<div id="petHomePanel"></div>';
    }

    if(!myView){
      myView = document.createElement('section');
      myView.id = 'myBaseView';
      basePage.insertBefore(myView, petSection);
    }

    [...basePage.children].forEach(el => {
      if(el === tabs || el === myView || el === petSection) return;
      myView.appendChild(el);
    });

    tabs.querySelectorAll('button').forEach(btn => {
      btn.onclick = () => switchBaseMode(btn.dataset.mode);
      btn.classList.toggle('active', btn.dataset.mode === currentMode);
    });

    renderDogHome();
    myView.classList.toggle('hide', currentMode === 'pet');
    petSection.classList.toggle('hide', currentMode !== 'pet');
    return { tabs, myView, petSection };
  }

  function switchBaseMode(mode){
    currentMode = mode === 'pet' ? 'pet' : 'my';
    const ui = ensureBaseLayout();
    if(!ui) return;
    ui.tabs.querySelectorAll('button').forEach(btn => btn.classList.toggle('active', btn.dataset.mode === currentMode));
    ui.myView.classList.toggle('hide', currentMode === 'pet');
    ui.petSection.classList.toggle('hide', currentMode !== 'pet');
    if(currentMode === 'pet'){
      renderDogHome();
      if(firstPetOpen){
        firstPetOpen = false;
        setTimeout(() => dogHomeAction('pet'), 250);
      }
    } else {
      stopAnim();
    }
  }

  async function dogHomeAction(action){
    if(busy) return;
    busy = true;
    disableButtons(true);
    const s = ensureState();
    const pet = qs('dogHomePet');
    const ball = qs('dogHomeBall');
    try{
      if(action === 'idle'){
        say('我在這裡陪你～');
        pet.className = 'dog-home-dog';
        pet.style.left = '50%';
        pet.style.bottom = '45px';
        loop('idle',4);
        return;
      }
      if(action === 'pet'){
        say('看到主人，我開心跑過來！');
        pet.className = 'dog-home-dog front';
        pet.style.left = '50%';
        pet.style.bottom = '70px';
        loop('run',10);
        await wait(1500);
        s.happy = clamp(s.happy + 4);
      }
      if(action === 'walk'){
        say('我在房間裡散散步～');
        pet.className = 'dog-home-dog';
        loop('walk',8);
        pet.style.left = '72%';
        await wait(1350);
        pet.style.left = '32%';
        await wait(1450);
        pet.style.left = '50%';
        await wait(850);
        s.energy = clamp(s.energy - 2);
      }
      if(action === 'feed'){
        say('我要去吃飯飯囉！');
        pet.className = 'dog-home-dog';
        loop('walk',8);
        pet.style.left = '77%';
        await wait(1350);
        pet.classList.add('eating');
        await playOnce('eat',6,2);
        say('吃飽了，好滿足！');
        s.hunger = clamp(s.hunger + 16);
        s.happy = clamp(s.happy + 3);
        addCoins(1);
        await wait(300);
        loop('walk',8);
        pet.className = 'dog-home-dog';
        pet.style.left = '50%';
        await wait(1350);
      }
      if(action === 'sleep'){
        say('我想去床邊休息一下。');
        pet.className = 'dog-home-dog';
        loop('walk',8);
        pet.style.left = '23%';
        await wait(1350);
        pet.className = 'dog-home-dog sleeping';
        loop('sleep',3);
        await wait(2600);
        say('睡飽了，精神變好了！');
        s.energy = clamp(s.energy + 18);
        addCoins(1);
        loop('walk',8);
        pet.className = 'dog-home-dog';
        pet.style.left = '50%';
        await wait(1350);
      }
      if(action === 'play'){
        say('球球！我要去追！');
        pet.className = 'dog-home-dog';
        ball.style.transform = 'translate(220px,-90px)';
        loop('run',10);
        pet.style.left = '72%';
        await wait(900);
        ball.style.transform = 'translate(-180px,-35px)';
        pet.style.left = '31%';
        await wait(1050);
        await playOnce('play',7,1);
        say('抓到球了，真好玩！');
        s.happy = clamp(s.happy + 10);
        s.energy = clamp(s.energy - 4);
        addCoins(1);
        ball.style.transform = 'none';
        pet.style.left = '50%';
        await wait(800);
      }
      s.totalCare = Number(s.totalCare||0) + (action === 'idle' || action === 'walk' || action === 'pet' ? 0 : 1);
      saveAll();
      renderDogHome();
      say(action === 'pet' ? '最喜歡你了！' : action === 'walk' ? '散步結束囉！' : '互動完成，獲得 1 枚守護金幣！');
    } finally {
      busy = false;
      disableButtons(false);
    }
  }

  function injectStyles(){
    if(qs('dogHomeInjectedStyle')) return;
    const style = document.createElement('style');
    style.id = 'dogHomeInjectedStyle';
    style.textContent = `
      .base-quick-tabs{display:flex;gap:10px;width:min(1480px,calc(100% - 24px));margin:14px auto 12px;padding:7px;border:1px solid #d7e6dd;border-radius:18px;background:#eef6f1}
      .base-quick-tabs button{flex:1;min-height:50px;border:0;border-radius:14px;background:#f8fbf9;color:#667c73;font-weight:1000;font-size:16px;cursor:pointer}
      .base-quick-tabs button.active[data-mode="my"]{background:#178263;color:#fff}
      .base-quick-tabs button.active[data-mode="pet"]{background:#d98d32;color:#fff}
      .dog-home-section{width:min(1480px,calc(100% - 24px));margin:0 auto 24px}
      .dog-home-shell{border:2px solid #9c6837;border-radius:24px;overflow:hidden;background:#f6ddb2;color:#5b3b22;box-shadow:0 12px 28px rgba(90,58,31,.13)}
      .dog-home-topbar{display:grid;grid-template-columns:auto 1fr auto;gap:14px;align-items:center;padding:13px 18px;background:linear-gradient(#c8894d,#b87438);color:#fff8e9}
      .dog-home-title{font-size:25px;font-weight:1000}
      .dog-home-subtitle{justify-self:center;padding:8px 14px;border-radius:16px;background:#fff1ca;color:#754920;font-weight:900}
      .dog-home-coin{padding:8px 13px;background:#fff1ca;color:#71461f;border-radius:15px;font-weight:900}
      .dog-home-switchers{display:flex;gap:8px;padding:10px 16px;background:#f9e9cb;border-bottom:1px solid #d7ad75}
      .dog-home-switchers button{flex:1;border:2px solid #cfaa76;border-radius:14px;padding:9px;background:#fff7e7;font-weight:1000}
      .dog-home-switchers button.active{background:#ffe4a2;border-color:#df972d}
      .dog-home-switchers button.coming{opacity:.65}
      .dog-home-room{position:relative;min-height:560px;overflow:hidden;background:linear-gradient(#fae9c9 0 75%,#d8a067 75%)}
      .dog-home-room:before{content:'';position:absolute;inset:0;opacity:.10;background-image:linear-gradient(rgba(90,60,35,.15) 1px,transparent 1px),linear-gradient(90deg,rgba(90,60,35,.15) 1px,transparent 1px);background-size:56px 56px}
      .dog-home-window{position:absolute;left:30px;top:28px;width:240px;height:130px;border:10px solid #b57940;border-radius:16px;background:linear-gradient(#9ed9f7 0 65%,#83c35d 65%);display:grid;place-items:center;font-size:30px}
      .dog-home-bed{position:absolute;left:55px;bottom:38px;font-size:80px}
      .dog-home-bowl{position:absolute;right:70px;bottom:38px;font-size:66px}
      .dog-home-ball{position:absolute;left:315px;bottom:62px;font-size:43px;transition:transform .45s ease}
      .dog-home-door{position:absolute;right:10px;top:165px;font-size:110px;opacity:.85}
      .dog-home-speech{position:absolute;left:50%;top:76px;transform:translateX(-50%);padding:10px 15px;border:2px solid #a56c36;border-radius:16px;background:#fff9e9;font-weight:900;opacity:0;z-index:2;max-width:280px;text-align:center}
      .dog-home-speech.show{animation:dogHomeSpeak 2.3s ease}
      .dog-home-stats{position:absolute;left:20px;top:185px;width:245px;padding:12px;border:2px solid #bd8b55;border-radius:15px;background:rgba(255,249,235,.94);line-height:1.5;font-size:13px;z-index:2}
      .dog-home-stats div{display:grid;grid-template-columns:62px 1fr 34px;gap:8px;align-items:center;margin:7px 0}
      .dog-home-stats i{display:block;height:12px;border-radius:999px;background:#eadfca;overflow:hidden}
      .dog-home-stats i b{display:block;height:100%;border-radius:999px;background:linear-gradient(90deg,#ef7889,#79bf57)}
      .dog-home-stats strong{text-align:right}
      .dog-home-frame-info{position:absolute;right:18px;top:18px;min-width:155px;padding:10px 14px;border-radius:14px;background:#2f4a3ee8;color:#fff;font-weight:1000;text-align:center;z-index:2}
      .dog-home-frame-info b,.dog-home-frame-info span{display:block}
      .dog-home-note{position:absolute;left:20px;top:355px;width:245px;padding:12px;border-radius:14px;background:#fffdf1e8;border:2px solid #c89354;font-weight:700;line-height:1.55;font-size:13px;z-index:2}
      .dog-home-dog{position:absolute;left:50%;bottom:45px;width:300px;height:220px;transform:translateX(-50%);display:flex;align-items:flex-end;justify-content:center;transition:left .85s cubic-bezier(.22,.7,.24,1),bottom .65s ease,transform .35s ease;z-index:3}
      .dog-home-dog img{max-width:100%;max-height:100%;object-fit:contain;filter:drop-shadow(0 10px 8px rgba(0,0,0,.14))}
      .dog-home-dog.front{bottom:72px;transform:translateX(-50%) scale(1.08)}
      .dog-home-dog.eating{transform:translateX(-50%) scale(.97)}
      .dog-home-dog.sleeping{bottom:45px;transform:translateX(-50%) scale(.95)}
      .dog-home-actions{display:grid;grid-template-columns:repeat(6,1fr);gap:9px;padding:14px 18px;background:#f3d293;border-top:3px solid #a97038}
      .dog-home-actions button{border:2px solid #b77a3c;border-radius:15px;background:linear-gradient(#fff8df,#f3c76d);padding:11px 5px;box-shadow:0 4px 0 #99622f;font-size:23px;cursor:pointer}
      .dog-home-actions button b{display:block;font-size:14px;color:#70471f;margin-top:2px}
      .dog-home-actions button:disabled{opacity:.55;cursor:not-allowed}
      @keyframes dogHomeSpeak{0%{opacity:0;transform:translate(-50%,8px)}10%,82%{opacity:1;transform:translate(-50%,0)}100%{opacity:0;transform:translate(-50%,-8px)}}
      @media(max-width:720px){
        .dog-home-topbar{grid-template-columns:1fr auto}
        .dog-home-subtitle{grid-column:1/-1;font-size:12px}
        .dog-home-room{min-height:650px}
        .dog-home-window{left:12px;width:175px;height:95px}
        .dog-home-stats{top:145px;width:195px;font-size:11px}
        .dog-home-note{top:330px;width:195px;font-size:11px}
        .dog-home-dog{width:245px;height:190px}
        .dog-home-bowl{right:12px}
        .dog-home-ball{left:210px}
        .dog-home-door{font-size:80px;right:-8px}
        .dog-home-frame-info{font-size:12px;min-width:118px}
        .dog-home-actions{grid-template-columns:repeat(3,1fr)}
      }`;
    document.head.appendChild(style);
  }

  function patch(name){
    const old = window[name];
    if(typeof old !== 'function' || old.__dogHomePatched) return;
    const wrapped = function(){
      const result = old.apply(this, arguments);
      setTimeout(() => ensureBaseLayout(), 0);
      return result;
    };
    wrapped.__dogHomePatched = true;
    window[name] = wrapped;
  }

  function install(){
    injectStyles();
    ensureState();
    ensureBaseLayout();
    patch('showBase');
    patch('renderBase');
    window.switchBaseMode = switchBaseMode;
    window.dogHomeAction = dogHomeAction;
  }

  if(document.readyState === 'loading') document.addEventListener('DOMContentLoaded', () => setTimeout(install, 200), {once:true});
  else setTimeout(install, 200);
})();
